type LRUCache struct {
	cap int
	ll  *list.List
	m   map[string]*list.Element
}

func NewLRUCache(cap int) *LRUCache {
	return &LRUCache{
		cap: cap,
		ll:  list.New(),
		m:   make(map[string]*list.Element),
	}
}

func (c *LRUCache) Get(key string) (int, bool) {
	el, ok := c.m[key]
	if !ok {
		return 0, false
	}
	c.ll.MoveToFront(el)
	return el.Value.(*entry).val, true
}

func (c *LRUCache) Put(key string, val int) {
	if c.cap <= 0 {
		return
	}
	if el, ok := c.m[key]; ok {
		el.Value.(*entry).val = val
		c.ll.MoveToFront(el)
		return
	}
	el := c.ll.PushFront(&entry{key: key, val: val})
	c.m[key] = el
	if c.ll.Len() > c.cap {
		back := c.ll.Back()
		if back != nil {
			delete(c.m, back.Value.(*entry).key)
			c.ll.Remove(back)
		}
	}
}
